import { prisma } from "@/src/lib/prisma";
import TaskListClient from "@/components/tasks/TaskListClient";

export default async function TasksPage() {
  // Veritabanından tüm dokümanları (Daily, Planning vb.) çekiyoruz
  const tasks = await prisma.task.findMany({
    orderBy: { 
      createdAt: 'desc' 
    }
  });

  return (
    <div className="p-6 space-y-6 animate-in fade-in duration-500">
      {/* Paylaştığın görsel yapıyı ve buton mantığını TaskListClient'a taşıdık. 
          Böylece hem veriler Server'dan geliyor hem de butonlar (Client) çalışıyor.
      */}
      <TaskListClient initialTasks={tasks} />
    </div>
  );
}